 WITH source_data AS (
         SELECT weather.id,
            weather."timestamp",
            weather.temperature_c,
            weather.wind_speed,
            weather.updated_at
           FROM public.weather
        ), cleaned AS (
         SELECT source_data.id AS weather_id,
            date_trunc('hour'::text, source_data."timestamp") AS observation_time,
            round((source_data.temperature_c)::numeric, 2) AS temperature_c,
            round((source_data.wind_speed)::numeric, 2) AS wind_speed_kmh,
            source_data.updated_at
           FROM source_data
          WHERE (source_data."timestamp" IS NOT NULL)
